INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (10990, 'Kiundu Komdodomitsɛ', 'dangme', 'Kiundu wala mi oti kake ji niyeni nɛ a je he gbi nɛ e ko bɔ lɛ. Kɛ e maa pee kɛ nɛ e nine maa su okplɔɔngmɛmi he enyɛɔ ɔmɛ a niyeni ɔmɛ a nɔ kɛje kɔpe enyɔ ɔmɛ a mi kɛɛ ngɛ ligbi kake nɔ? Nível: First paragraphs. Ilustração: Alex Zablon.', 'http://africanstorybook.org/illustrations/covers/18340.png', NULL, 1819, 35, 30, 'asp-18340', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (10991, 'Matsɛ Kayanja Kɛ E Bi Yo Ɔ', 'dangme', 'Awulɛho suɔmi anyazia ko nɛ kɔɔ matsɛ Nível: Longer paragraphs. Ilustração: Natalie Propa.', 'http://africanstorybook.org/illustrations/covers/18341.png', NULL, 1819, 35, 30, 'asp-18341', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (10992, 'Sungura Amdanganya Ndovu', 'sw', 'Hadithi hii inatuonyesha sababu sungura anakimbia kwa kasi na jinsi alivyomdanganya ndovu rafikiye. Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/18342.png', NULL, 1096, 35, 30, 'asp-18342', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (10993, 'Maate Kɛ Maalai Sla Nana', 'dangme', 'Maate kɛ Maalai suɔ nɛ a sla a na ngɛ kɔpe blɔhami fia. Nível: First paragraphs. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/18343.png', NULL, 1816, 35, 30, 'asp-18343', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (10994, 'Umoja', 'sw', 'Wanakijiji wanaungana kubadilisha maisha yao. Nível: First words. Ilustração: Vusi Malindi.', 'http://africanstorybook.org/illustrations/covers/18344.png', NULL, 1096, 35, 30, 'asp-18344', 'cc-by', 0, NULL);
